'use strict';
const $ = id => document.getElementById(id), cfg = window.CCAR_CONFIG || {}, connected = !!(cfg.supabaseUrl && cfg.supabaseAnonKey);
const money = n => new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL',maximumFractionDigits:0}).format(n);
let vehicles=[], adminVehicles=[], session=null, existingPhotos=[], previews=[];
const safe = s => String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const photoURL = path => cfg.supabaseUrl+'/storage/v1/object/public/vehicle-photos/'+path.split('/').map(encodeURIComponent).join('/');
function inform(text){$('messageText').textContent=text;$('message').showModal();}
function adminMessage(text){$('adminMessage').hidden=!text;$('adminMessage').textContent=text;}
function analyticsSession(){let id=localStorage.getItem('ccar-analytics-session');if(!id){id=crypto.randomUUID();localStorage.setItem('ccar-analytics-session',id);}return id;}
function trackVehicleEvent(vehicleId,eventType){if(!connected||!vehicleId)return;if(window.ccarHasAnalyticsConsent?.()!==true){window.addEventListener('ccar:analytics-consent-granted',()=>trackVehicleEvent(vehicleId,eventType),{once:true});return;}fetch(cfg.supabaseUrl+'/rest/v1/rpc/track_vehicle_event',{method:'POST',headers:{apikey:cfg.supabaseAnonKey,'Content-Type':'application/json'},body:JSON.stringify({p_vehicle_id:vehicleId,p_event_type:eventType,p_session_id:analyticsSession()})}).catch(()=>{});}
function storeSession(value){session=value;sessionStorage.setItem('ccar-session',JSON.stringify(value));}
async function request(path,options={},authorized=false){
 if(!connected)throw Error('Conecte o Supabase para ativar este recurso.');
 if(authorized&&session?.expires_at<Date.now()/1000+60){const r=await fetch(cfg.supabaseUrl+'/auth/v1/token?grant_type=refresh_token',{method:'POST',headers:{apikey:cfg.supabaseAnonKey,'Content-Type':'application/json'},body:JSON.stringify({refresh_token:session.refresh_token})});if(!r.ok){storeSession(null);throw Error('Sua sessão expirou. Entre novamente.');}const s=await r.json();storeSession({...s,expires_at:Date.now()/1000+s.expires_in});}
 const headers={apikey:cfg.supabaseAnonKey,...(authorized?{Authorization:'Bearer '+session?.access_token}:{}),...options.headers};
 const r=await fetch(cfg.supabaseUrl+path,{...options,headers});if(!r.ok){const body=await r.json().catch(()=>({}));throw Error(body.msg||body.message||body.error_description||'Não foi possível concluir. Tente novamente.');}if(r.status===204)return null;return r.json().catch(()=>null);
}
function card(v){return `<a class="card" href="veiculo.html?id=${encodeURIComponent(v.id)}">${v.photos?.length?`<img src="${safe(photoURL(v.photos[0]))}" loading="lazy" alt="${safe(v.make+' '+v.model)}">`:'<img src="assets/logo.png" alt="Veículo sem foto" loading="lazy" style="object-fit:contain;padding:40px">'}<div class="card-body"><span class="badge">${safe(v.category)} • ${safe(v.year)}</span><h3>${safe(v.make)} ${safe(v.model)}</h3><p>${safe(v.version)}</p><p>${Number(v.km).toLocaleString('pt-BR')} km · ${safe(v.transmission)} · ${safe(v.fuel)}</p><strong>${money(v.price)}</strong><div class="card-action">Ver veículo</div></div></a>`;}
function render(){document.querySelectorAll('[data-type]').forEach(b=>{const active=b.dataset.type===$('category').value;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));});let list=vehicles.filter(v=>[v.make,v.model,v.version].join(' ').toLocaleLowerCase('pt-BR').includes($('search').value.toLocaleLowerCase('pt-BR'))&&(!$('category').value||v.category===$('category').value));if($('sort').value==='low')list.sort((a,b)=>a.price-b.price);if($('sort').value==='high')list.sort((a,b)=>b.price-a.price);$('count').textContent=list.length+' veículo'+(list.length===1?'':'s')+' disponível'+(list.length===1?'':'s');$('vehicles').innerHTML=list.length?list.map(card).join(''):`<div class="empty"><img src="assets/logo.png" alt=""><h3>${vehicles.length?'Nenhum veículo encontrado.':'Estoque em atualização.'}</h3><p>${vehicles.length?'Experimente outra busca ou selecione todos os tipos.':'Os veículos serão publicados em breve, com fotos e informações completas.'}</p></div>`;const featured=vehicles.filter(v=>v.featured).slice(0,2);$('featured').innerHTML=featured.length?featured.map(card).join(''):'<div class="feature-note"><span class="eyebrow">ESTOQUE EM BREVE</span><h3>Veículos em destaque.</h3><p>Confira aqui os veículos em destaque assim que o estoque for publicado.</p><a href="#estoque">Explorar estoque</a></div>';}
async function loadVehicles(){if(!connected){vehicles=[];render();return;}try{vehicles=await request('/rest/v1/vehicles?status=eq.published&select=*&order=created_at.desc');render();}catch(e){$('count').textContent='Estoque temporariamente indisponível';$('vehicles').innerHTML='<div class="empty"><h3>Não conseguimos carregar o estoque.</h3><p>Tente novamente em alguns instantes.</p><button class="outline" id="retry">Tentar novamente</button></div>';$('retry').onclick=loadVehicles;}}
function contact(v){if(!cfg.whatsapp){inform('O canal de atendimento da C CAR será disponibilizado em breve.');return;}if(v)trackVehicleEvent(v.id,'contact');window.ccarTrackMeta?.('Contact',v?{content_ids:[v.id],content_name:`${v.make} ${v.model}`,content_type:'vehicle',value:Number(v.price)||0,currency:'BRL'}:{content_name:'Contato geral'});const text=v?`Olá! Tenho interesse no ${v.make} ${v.model} ${v.version||''}, ano ${v.year}, anunciado por ${money(v.price)} na C CAR.`:'Olá! Vim pelo site da C CAR e gostaria de conhecer o estoque.';window.open('https://wa.me/'+cfg.whatsapp.replace(/\D/g,'')+'?text='+encodeURIComponent(text),'_blank','noopener,noreferrer');}
function details(v){trackVehicleEvent(v.id,'view');$('detailBody').innerHTML=`${v.photos?.length?`<img class="detail-cover" id="detailCover" src="${safe(photoURL(v.photos[0]))}" alt="${safe(v.make+' '+v.model)}"><div class="gallery">${v.photos.map((p,i)=>`<button data-gallery="${i}" aria-label="Ver foto ${i+1}"><img src="${safe(photoURL(p))}" alt="Foto ${i+1}"></button>`).join('')}</div>`:''}<span class="eyebrow">${safe(v.category)}</span><h2>${safe(v.make)} ${safe(v.model)}</h2><p>${safe(v.version)}</p><strong class="detail-price">${money(v.price)}</strong><div class="specs"><span>${safe(v.year)}</span><span>${Number(v.km).toLocaleString('pt-BR')} km</span><span>${safe(v.transmission)}</span><span>${safe(v.fuel)}</span></div><p class="description">${safe(v.description)}</p><button class="gold" id="vehicleContact">Tenho interesse</button>`;$('detail').showModal();$('vehicleContact').onclick=()=>contact(v);$('detailBody').querySelectorAll('[data-gallery]').forEach(b=>b.onclick=()=>{$('detailCover').src=photoURL(v.photos[+b.dataset.gallery]);});}
document.addEventListener('click',e=>{const close=e.target.closest('[data-close]');if(close)$(close.dataset.close).close();const b=e.target.closest('[data-vehicle]');if(b){const v=vehicles.find(v=>v.id===b.dataset.vehicle);if(v)details(v);}});
for(const id of ['search','category','sort'])$(id).addEventListener('input',render);
$('contact').onclick=()=>contact();$('headerContact').onclick=()=>contact();$('stockSearch').onclick=()=>{const term=$('search').value.trim()||$('category').value;if(term)window.ccarTrackMeta?.('Search',{search_string:term});$('estoque').scrollIntoView({behavior:'smooth'});};document.querySelectorAll('[data-type]').forEach(b=>b.onclick=()=>{$('category').value=b.dataset.type;render();});$('year').textContent=new Date().getFullYear();$('address').textContent=cfg.address||'';
function openAdmin(){window.location.href='admin.html';}
$('adminOpen').onclick=openAdmin;$('footerAdmin').onclick=openAdmin;
$('setupNotice').hidden=connected;$('loginButton').disabled=!connected;
$('loginForm').onsubmit=async e=>{e.preventDefault();$('loginButton').disabled=true;adminMessage('Verificando acesso…');try{const s=await request('/auth/v1/token?grant_type=password',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:$('email').value.trim(),password:$('password').value})});storeSession({...s,expires_at:Date.now()/1000+s.expires_in});$('password').value='';await loadPanel();}catch(err){adminMessage('Não foi possível entrar. Confira seu e-mail, senha e autorização da equipe.');}finally{$('loginButton').disabled=!connected;}};
async function loadPanel(){try{const allowed=await request('/rest/v1/admin_users?select=user_id',{},true);if(!allowed?.some(a=>a.user_id===session.user.id)){storeSession(null);throw Error('Este usuário não foi autorizado para administrar a C CAR.');}adminVehicles=await request('/rest/v1/vehicles?select=*&order=created_at.desc',{},true);$('loginView').hidden=true;$('panel').hidden=false;adminMessage('');renderAdmin();}catch(e){$('loginView').hidden=false;$('panel').hidden=true;adminMessage(e.message);}}
function renderAdmin(){if(window.clearPrivateUi)window.clearPrivateUi();$('adminList').innerHTML=adminVehicles.length?adminVehicles.map(v=>`<div class="admin-row"><div><strong>${safe(v.make+' '+v.model)}</strong><p>${safe(v.year)} • ${money(v.price)} • ${{draft:'Rascunho',published:'Disponível',sold:'Vendido'}[v.status]}</p></div><div><button data-private="${safe(v.id)}">Dados privados / Word</button> <button data-edit="${safe(v.id)}">Editar anúncio</button> <button data-delete="${safe(v.id)}">Excluir</button></div></div>`).join(''):'<p>Seu estoque está vazio. Cadastre o primeiro veículo.</p>';$('adminList').querySelectorAll('[data-private]').forEach(b=>b.onclick=()=>window.openPrivateVehicle(b.dataset.private));$('adminList').querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>edit(adminVehicles.find(v=>v.id===b.dataset.edit)));$('adminList').querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>removeVehicle(b.dataset.delete));}
function clearPreviews(){previews.forEach(URL.revokeObjectURL);previews=[];}
function edit(v){clearPreviews();$('vehicleForm').reset();$('vehicleForm').hidden=false;$('formTitle').textContent=v?'Editar veículo':'Novo veículo';$('vehicleId').value=v?.id||'';existingPhotos=v?.photos?.slice()||[];const fields={make:'make',model:'model',version:'version',vehicleYear:'year',price:'price',km:'km',transmission:'transmission',type:'category',fuel:'fuel',status:'status',description:'description'};if(v){for(const [id,key]of Object.entries(fields))$(id).value=v[key]??'';$('highlight').checked=v.featured;}$('photoPreview').innerHTML=existingPhotos.map((p,i)=>`<div><img src="${safe(photoURL(p))}" alt="Foto ${i+1}"><button type="button" data-remove-photo="${i}">Remover</button></div>`).join('');$('photoPreview').querySelectorAll('[data-remove-photo]').forEach(b=>b.onclick=()=>{existingPhotos[+b.dataset.removePhoto]=null;b.parentElement.remove();});$('vehicleForm').scrollIntoView({behavior:'smooth',block:'start'});}
$('newVehicle').onclick=()=>edit();$('cancelEdit').onclick=()=>{$('vehicleForm').hidden=true;clearPreviews();};
$('photos').onchange=()=>{clearPreviews();$('photoPreview').querySelectorAll('.new-photo').forEach(el=>el.remove());for(const f of $('photos').files){const url=URL.createObjectURL(f);previews.push(url);const img=document.createElement('img');img.className='new-photo';img.src=url;img.alt=f.name;$('photoPreview').append(img);}};
async function removeVehicle(id){if(!confirm('Excluir este veículo e suas fotos? Esta ação não pode ser desfeita.'))return;try{const v=adminVehicles.find(v=>v.id===id);await request('/rest/v1/vehicles?id=eq.'+id,{method:'DELETE'},true);if(v.photos.length)await request('/storage/v1/object/vehicle-photos',{method:'DELETE',headers:{'Content-Type':'application/json'},body:JSON.stringify({prefixes:v.photos})},true);await loadPanel();await loadVehicles();adminMessage('Veículo excluído.');}catch(e){adminMessage(e.message);}}
$('vehicleForm').onsubmit=async e=>{e.preventDefault();const files=[...$('photos').files];if(files.length+existingPhotos.filter(Boolean).length>30){adminMessage('Use no máximo 30 fotos por veículo.');return;}if(files.some(f=>!['image/jpeg','image/png','image/webp'].includes(f.type)||f.size>15*1024*1024)){adminMessage('Use fotos JPEG, PNG ou WebP de até 15 MB cada.');return;}$('saveVehicle').disabled=true;const id=$('vehicleId').value||crypto.randomUUID(),uploads=[];let saved=false;try{const photos=existingPhotos.filter(Boolean);for(let i=0;i<files.length;i++){adminMessage(`Enviando foto ${i+1} de ${files.length}…`);const f=files[i],ext={'image/jpeg':'jpg','image/png':'png','image/webp':'webp'}[f.type],path=id+'/'+crypto.randomUUID()+'.'+ext;await request('/storage/v1/object/vehicle-photos/'+path,{method:'POST',headers:{'Content-Type':f.type,'Cache-Control':'max-age=31536000'},body:f},true);uploads.push(path);photos.push(path);}const record={id,make:$('make').value.trim(),model:$('model').value.trim(),version:$('version').value.trim(),year:+$('vehicleYear').value,price:+$('price').value,km:+$('km').value,transmission:$('transmission').value,category:$('type').value,fuel:$('fuel').value,status:$('status').value,description:$('description').value.trim(),featured:$('highlight').checked,photos};const old=adminVehicles.find(v=>v.id===id);await request('/rest/v1/vehicles'+(old?'?id=eq.'+id:''),{method:old?'PATCH':'POST',headers:{'Content-Type':'application/json',Prefer:'return=minimal'},body:JSON.stringify(record)},true);saved=true;const removed=old?.photos.filter(p=>!photos.includes(p))||[];if(removed.length)await request('/storage/v1/object/vehicle-photos',{method:'DELETE',headers:{'Content-Type':'application/json'},body:JSON.stringify({prefixes:removed})},true);$('vehicleForm').hidden=true;clearPreviews();await loadPanel();await loadVehicles();adminMessage('Veículo salvo com sucesso.');}catch(e){if(!saved&&uploads.length)await request('/storage/v1/object/vehicle-photos',{method:'DELETE',headers:{'Content-Type':'application/json'},body:JSON.stringify({prefixes:uploads})},true).catch(()=>{});adminMessage(saved?'Veículo salvo. Algumas fotos removidas não puderam ser apagadas do armazenamento.':e.message);}finally{$('saveVehicle').disabled=false;}};
$('logout').onclick=async()=>{await request('/auth/v1/logout',{method:'POST'},true).catch(()=>{});storeSession(null);if(window.clearPrivateUi)window.clearPrivateUi();$('panel').hidden=true;$('loginView').hidden=false;$('vehicleForm').hidden=true;adminMessage('');};
try{session=JSON.parse(sessionStorage.getItem('ccar-session'));}catch(e){session=null;}loadVehicles();
